def choose_move(observation):
    px, py = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    opp_x, opp_y = observation.get('opponent_position', (px, py))

    def dist(x, y): return abs(x - px) + abs(y - py)
    target = None
    min_dist = float('inf')
    for rx, ry in resources:
        d = dist(rx, ry)
        if d < min_dist:
            min_dist = d
            target = (rx, ry)
    if target:
        dx = (target[0] - px)
        dy = (target[1] - py)
        if dx != 0:
            dx = dx // abs(dx)
        if dy != 0:
            dy = dy // abs(dy)
        new_x, new_y = px + dx, py + dy
        if 0 <= new_x < width and 0 <= new_y < height and (new_x, new_y) not in obstacles:
            return [dx, dy]
    # No resources or blocked, move towards opponent
    dx = (opp_x - px)
    dy = (opp_y - py)
    if dx != 0:
        dx = dx // abs(dx)
    if dy != 0:
        dy = dy // abs(dy)
    new_x, new_y = px + dx, py + dy
    if 0 <= new_x < width and 0 <= new_y < height and (new_x, new_y) not in obstacles:
        return [dx, dy]
    # Can't move towards opponent, try to move randomly
    for d_x, d_y in [(-1,0),(1,0),(0,-1),(0,1)]:
        nx, ny = px + d_x, py + d_y
        if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
            return [d_x, d_y]
    return [0, 0]
